import android.media.MediaRecorder
import android.os.Build
class Rec(ctx:android.content.Context){
  private val r=if(Build.VERSION.SDK_INT>=31)MediaRecorder(ctx)else @Suppress("DEPRECATION")MediaRecorder()
  fun start(){r.setAudioSource(MediaRecorder.AudioSource.MIC);r.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);r.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);r.setOutputFile("{{file_path}}");r.prepare();r.start()}
  fun stop(){r.stop();r.release()}}
